class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}
        self.min_freq = 0

    def get(self, key):
        if key not in self.key_to_val:
            return -1

        # Update frequency
        freq = self.key_to_freq[key]
        self.key_to_freq[key] += 1

        # Remove from old frequency list
        self.freq_to_keys[freq].remove(key)
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if freq == self.min_freq:
                self.min_freq += 1

        # Add to new frequency list
        if freq + 1 not in self.freq_to_keys:
            self.freq_to_keys[freq + 1] = []
        self.freq_to_keys[freq + 1].append(key)

        return self.key_to_val[key]

    def put(self, key, value):
        if self.capacity == 0:
            return

        if key in self.key_to_val:
            # Update existing key
            self.key_to_val[key] = value
            self.get(key)  # This will update frequency
            return

        if len(self.key_to_val) >= self.capacity:
            # Remove LFU item
            lfu_keys = self.freq_to_keys[self.min_freq]
            lru_key = lfu_keys.pop(0)
            if not lfu_keys:
                del self.freq_to_keys[self.min_freq]

            del self.key_to_val[lru_key]
            del self.key_to_freq[lru_key]

        # Add new key
        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        self.min_freq = 1
        if 1 not in self.freq_to_keys:
            self.freq_to_keys[1] = []
        self.freq_to_keys[1].append(key)

