def count_bits_up_to(x):
    if x < 0:
        # For negative numbers, we count bits in two's complement
        # We use the fact that for 32-bit signed integers:
        # count_bits_up_to(-1) = 32 * 2^31
        # But we need to be more careful
        return 32 * (x + 1) + count_bits_up_to(~x)

    if x < 0:
        return 0

    # For non-negative numbers, we compute bit count using bit manipulation
    count = 0
    bit_pos = 0
    while (1 << bit_pos) <= x:
        # Count how many numbers in [0, x] have bit at position bit_pos set
        cycle_length = 1 << (bit_pos + 1)
        full_cycles = (x + 1) // cycle_length
        remainder = (x + 1) % cycle_length

        # In each full cycle, exactly half the numbers have bit_pos set
        count += full_cycles * (1 << bit_pos)

        # For the remainder, count how many numbers in [0, remainder-1] have bit_pos set
        if remainder > (1 << bit_pos):
            count += remainder - (1 << bit_pos)

        bit_pos += 1

    return count

